insert into public.stilnytsi_materials (slug, data, position) values ('symony-grey', '{"slug":"symony-grey","name":"Симонівський граніт (Symony Grey)","material":"granit","family":"Граніт","origin":"Україна","tone":"сіро-бежевий","finishes":["полірований","шліфований"],"thicknesses":[20,30],"applications":["стільниці","сходи","фасади"],"description":"Симонівський граніт (Symony Grey) — сірий камінь середнього зерна з теплим бежевим підтоном. М’якший за холодні сірі граніти, тому добре поєднується з деревом і латунню в інтер’єрі; на вулиці йде термообробленим на сходи й фасад.","image":"/materials/symony-grey.webp","cardImage":"/materials/symony-grey.webp","care":"Нейтральний засіб; для природного каменю перевіряти просочення.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":0,"unit":"м²","currency":"грн"}}'::jsonb, 200) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_materials (slug, data, position) values ('caviale-nero', '{"slug":"caviale-nero","name":"Новоселівський граніт (Caviale Nero)","material":"granit","family":"Граніт","origin":"Україна","tone":"майже чорний","finishes":["полірований","шліфований"],"thicknesses":[20,30],"applications":["стільниці","сходи","фасади"],"description":"Новоселівський граніт (Caviale Nero) — дуже темно-сірий, майже чорний граніт із дрібними білими цятками, як чорна ікра. Альтернатива габро для тих, хто хоче живішу поверхню: зерно видно зблизька, з відстані камінь читається чорним.","image":"/materials/caviale-nero.webp","cardImage":"/materials/caviale-nero.webp","care":"Нейтральний засіб; для природного каменю перевіряти просочення.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":0,"unit":"м²","currency":"грн"}}'::jsonb, 201) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_materials (slug, data, position) values ('withered', '{"slug":"withered","name":"Новоданилівський граніт (Withered)","material":"granit","family":"Граніт","origin":"Україна","tone":"бордово-червоний","finishes":["полірований","шліфований"],"thicknesses":[20,30],"applications":["сходи","фасади","бруківка"],"description":"Новоданилівський граніт (Withered) — приглушений бордово-червоний камінь із коричневим відтінком і темними вкрапленнями. Спокійніший за яскраві червоні граніти; типовий вибір для фасадного цоколя, сходів і бруківки.","image":"/materials/withered.webp","cardImage":"/materials/withered.webp","care":"Нейтральний засіб; для природного каменю перевіряти просочення.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":0,"unit":"м²","currency":"грн"}}'::jsonb, 202) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_materials (slug, data, position) values ('rosso-toledo', '{"slug":"rosso-toledo","name":"Омелянівський граніт (Rosso Toledo)","material":"granit","family":"Граніт","origin":"Житомирська область, Україна","tone":"рожево-червоний","finishes":["полірований","шліфований"],"thicknesses":[20,30],"applications":["стільниці","сходи","фасади"],"description":"Омелянівський граніт (Rosso Toledo) — крупнозернистий рожево-червоний камінь із сірими та чорними кристалами. Виразний рисунок для стільниць і сходів, які мають бути помітними; у термообробленому фініші стає світлішим і матовим.","image":"/materials/rosso-toledo.webp","cardImage":"/materials/rosso-toledo.webp","care":"Нейтральний засіб; для природного каменю перевіряти просочення.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":0,"unit":"м²","currency":"грн"}}'::jsonb, 203) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_materials (slug, data, position) values ('karmin', '{"slug":"karmin","name":"Крупський граніт (Karmin)","material":"granit","family":"Граніт","origin":"Житомирська область, Україна","tone":"карміново-рожевий","finishes":["полірований","шліфований"],"thicknesses":[20,30],"applications":["сходи","фасади","бруківка"],"description":"Крупський граніт (Karmin) — насичений карміново-рожевий граніт середнього зерна, рівномірний, без плям. Один із найяскравіших українських каменів: фасадні вставки, сходи, бруківка з кольоровим акцентом.","image":"/materials/karmin.webp","cardImage":"/materials/karmin.webp","care":"Нейтральний засіб; для природного каменю перевіряти просочення.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":0,"unit":"м²","currency":"грн"}}'::jsonb, 204) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_materials (slug, data, position) values ('ukrainian-autumn', '{"slug":"ukrainian-autumn","name":"Василівський граніт (Ukrainian Autumn)","material":"granit","family":"Граніт","origin":"Житомирська область, Україна","tone":"коричнево-зелений","finishes":["полірований","шліфований"],"thicknesses":[20,30],"applications":["стільниці","сходи","фасади"],"description":"Василівський граніт (Ukrainian Autumn) — крупнозернистий камінь в осінніх тонах: оливковий, іржавий, чорний. Кожна плита має власний рисунок, тому його беруть на стільниці й каміни, де камінь є головним елементом.","image":"/materials/ukrainian-autumn.webp","cardImage":"/materials/ukrainian-autumn.webp","care":"Нейтральний засіб; для природного каменю перевіряти просочення.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":0,"unit":"м²","currency":"грн"}}'::jsonb, 205) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_materials (slug, data, position) values ('leopard-brown', '{"slug":"leopard-brown","name":"Брусилівський граніт (Leopard)","material":"granit","family":"Граніт","origin":"Житомирська область, Україна","tone":"коричневий","finishes":["полірований","шліфований"],"thicknesses":[20,30],"applications":["сходи","фасади","бруківка"],"description":"Брусилівський граніт (Leopard) — коричнево-сіре тло з великими темними плямами, крупне зерно. Не плутати з Корнинським, який має ту саму комерційну назву, але сірий. Зовнішні сходи, цоколь, бруківка.","image":"/materials/leopard-brown.webp","cardImage":"/materials/leopard-brown.webp","care":"Нейтральний засіб; для природного каменю перевіряти просочення.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":0,"unit":"м²","currency":"грн"}}'::jsonb, 206) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_materials (slug, data, position) values ('rosa-kyshyn', '{"slug":"rosa-kyshyn","name":"Кишинський граніт (Rosa Kyshyn)","material":"granit","family":"Граніт","origin":"Житомирська область, Україна","tone":"рожево-коричневий","finishes":["полірований","шліфований"],"thicknesses":[20,30],"applications":["сходи","фасади","бруківка"],"description":"Кишинський граніт (Rosa Kyshyn) — рожево-коричневий граніт середнього зерна з чорними цятками. Теплий камінь для фасадів і сходів, добре тримає полірування й не вигорає на сонці.","image":"/materials/rosa-kyshyn.webp","cardImage":"/materials/rosa-kyshyn.webp","care":"Нейтральний засіб; для природного каменю перевіряти просочення.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":0,"unit":"м²","currency":"грн"}}'::jsonb, 207) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_materials (slug, data, position) values ('calacatta-oro', '{"slug":"calacatta-oro","name":"Мармур Calacatta Oro","material":"marmur","family":"Мармур","origin":"Італія","tone":"білий із золотистими жилами","finishes":["полірований","шліфований"],"thicknesses":[20,30],"applications":["стільниці","ванна","каміни"],"description":"Мармур Calacatta Oro — яскраво-білий італійський мармур із широкими золотисто-сірими жилами. Найстатусніший білий камінь: острови, каміни, панно у ванній. Потребує просочення й нейтральних засобів, зате старіє благородно.","image":"/materials/calacatta-oro.webp","cardImage":"/materials/calacatta-oro.webp","care":"Нейтральний pH, просочення та негайне видалення кислот.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":0,"unit":"м²","currency":"грн"}}'::jsonb, 208) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_materials (slug, data, position) values ('statuario', '{"slug":"statuario","name":"Мармур Statuario","material":"marmur","family":"Мармур","origin":"Італія","tone":"чисто білий із сірими жилами","finishes":["полірований","шліфований"],"thicknesses":[20,30],"applications":["стільниці","ванна","каміни"],"description":"Мармур Statuario — чисто білий апуанський мармур із тонкими чіткими темно-сірими жилами, камінь скульпторів. Для стільниць і ванн, де потрібен найбіліший фон із графічним рисунком.","image":"/materials/statuario.webp","cardImage":"/materials/statuario.webp","care":"Нейтральний pH, просочення та негайне видалення кислот.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":0,"unit":"м²","currency":"грн"}}'::jsonb, 209) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_materials (slug, data, position) values ('marmara-white', '{"slug":"marmara-white","name":"Мармур Marmara White","material":"marmur","family":"Мармур","origin":"Туреччина","tone":"білий зі смугами","finishes":["полірований","шліфований"],"thicknesses":[20,30],"applications":["ванна","підлога","підвіконня"],"description":"Мармур Marmara White — білий турецький мармур із паралельними прямими сірими смугами. Спокійніший і доступніший за Carrara; підлоги, підвіконня, облицювання ванної.","image":"/materials/marmara-white.webp","cardImage":"/materials/marmara-white.webp","care":"Нейтральний pH, просочення та негайне видалення кислот.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":0,"unit":"м²","currency":"грн"}}'::jsonb, 210) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_materials (slug, data, position) values ('arabescato', '{"slug":"arabescato","name":"Мармур Arabescato","material":"marmur","family":"Мармур","origin":"Італія","tone":"білий із сірою сіткою жил","finishes":["полірований","шліфований"],"thicknesses":[20,30],"applications":["ванна","каміни","стільниці"],"description":"Мармур Arabescato — білий мармур із сірими жилами, що сплітаються в сітку-арабеску. Виразніший за Carrara, стриманіший за Calacatta; каміни, стіни у ванній, столи.","image":"/materials/arabescato.webp","cardImage":"/materials/arabescato.webp","care":"Нейтральний pH, просочення та негайне видалення кислот.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":0,"unit":"м²","currency":"грн"}}'::jsonb, 211) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_materials (slug, data, position) values ('botticino', '{"slug":"botticino","name":"Мармур Botticino Classico","material":"marmur","family":"Мармур","origin":"Італія","tone":"бежевий","finishes":["полірований","шліфований"],"thicknesses":[20,30],"applications":["підлога","ванна","підвіконня"],"description":"Мармур Botticino Classico — рівний бежевий мармур із дрібним, ледь помітним рисунком. Класика для підлог і сходів в інтер’єрі: теплий, спокійний, добре поєднується з будь-яким кольором.","image":"/materials/botticino.webp","cardImage":"/materials/botticino.webp","care":"Нейтральний pH, просочення та негайне видалення кислот.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":0,"unit":"м²","currency":"грн"}}'::jsonb, 212) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_materials (slug, data, position) values ('bardiglio', '{"slug":"bardiglio","name":"Мармур Bardiglio Nuvolato","material":"marmur","family":"Мармур","origin":"Італія","tone":"сіро-блакитний","finishes":["полірований","шліфований"],"thicknesses":[20,30],"applications":["ванна","підлога","каміни"],"description":"Мармур Bardiglio Nuvolato — сіро-блакитний хмаристий мармур зі світлішими розмитими смугами. Холодний тон для ванних і камінів у сучасних інтер’єрах, де білий мармур здається надто яскравим.","image":"/materials/bardiglio.webp","cardImage":"/materials/bardiglio.webp","care":"Нейтральний pH, просочення та негайне видалення кислот.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":0,"unit":"м²","currency":"грн"}}'::jsonb, 213) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_materials (slug, data, position) values ('super-white', '{"slug":"super-white","name":"Кварцит Super White","material":"kvarcyt","family":"Кварцит","origin":"Бразилія","tone":"білий із сірим","finishes":["полірований","шліфований"],"thicknesses":[20,30],"applications":["стільниці","острови","ванна"],"description":"Кварцит Super White — білий камінь із м’якими сірими плямами, зовні схожий на Carrara, але значно твердіший і не реагує на кислоти. Найпопулярніший кварцит для кухонних стільниць.","image":"/materials/super-white.webp","cardImage":"/materials/super-white.webp","care":"Нейтральний засіб; для природного каменю перевіряти просочення.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":0,"unit":"м²","currency":"грн"}}'::jsonb, 214) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_materials (slug, data, position) values ('white-macaubas', '{"slug":"white-macaubas","name":"Кварцит White Macaubas","material":"kvarcyt","family":"Кварцит","origin":"Бразилія","tone":"білий у смужку","finishes":["полірований","шліфований"],"thicknesses":[20,30],"applications":["стільниці","острови","ванна"],"description":"Кварцит White Macaubas — білий кварцит із тонкими паралельними сірими лініями. Графічний і спокійний, добре виглядає на довгих стільницях і островах.","image":"/materials/white-macaubas.webp","cardImage":"/materials/white-macaubas.webp","care":"Нейтральний засіб; для природного каменю перевіряти просочення.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":0,"unit":"м²","currency":"грн"}}'::jsonb, 215) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_materials (slug, data, position) values ('mont-blanc', '{"slug":"mont-blanc","name":"Кварцит Mont Blanc","material":"kvarcyt","family":"Кварцит","origin":"Бразилія","tone":"білий із золотистим","finishes":["полірований","шліфований"],"thicknesses":[20,30],"applications":["стільниці","острови"],"description":"Кварцит Mont Blanc — білий камінь із сіро-золотистими хвилями. Теплий варіант білого кварциту для кухонь із дерев’яними фасадами.","image":"/materials/mont-blanc.webp","cardImage":"/materials/mont-blanc.webp","care":"Нейтральний засіб; для природного каменю перевіряти просочення.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":0,"unit":"м²","currency":"грн"}}'::jsonb, 216) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_materials (slug, data, position) values ('sea-pearl', '{"slug":"sea-pearl","name":"Кварцит Sea Pearl","material":"kvarcyt","family":"Кварцит","origin":"Бразилія","tone":"сіро-зелений","finishes":["полірований","шліфований"],"thicknesses":[20,30],"applications":["стільниці","острови","ванна"],"description":"Кварцит Sea Pearl — сіро-зелений перламутровий камінь із хвилястими світлими жилами. Незвичний відтінок для стільниць і ванн, зберігає твердість кварциту.","image":"/materials/sea-pearl.webp","cardImage":"/materials/sea-pearl.webp","care":"Нейтральний засіб; для природного каменю перевіряти просочення.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":0,"unit":"м²","currency":"грн"}}'::jsonb, 217) on conflict (slug) do update set data = excluded.data;
